(** * Register file for the Sail RISC-V model (generated by scripts/gen-regfile.py)

    One field per register family of [type_of_register], so that reads
    ([rd]) and updates ([upd_reg]) compute without dependent casts. *)

From stdpp Require Import base.
From SailStdpp Require Import Base.
From Riscv Require Import rv64d_types.

Record regfile : Type := mkRegfile {
  f_HartState : register_HartState -> HartState;
  f_Privilege : register_Privilege -> Privilege;
  f_bitvector_1 : register_bitvector_1 -> ((mword 1));
  f_bitvector_128 : register_bitvector_128 -> ((mword 128));
  f_bitvector_192 : register_bitvector_192 -> ((mword 192));
  f_bitvector_3 : register_bitvector_3 -> ((mword 3));
  f_bitvector_32 : register_bitvector_32 -> ((mword 32));
  f_bitvector_320 : register_bitvector_320 -> ((mword 320));
  f_bitvector_4 : register_bitvector_4 -> ((mword 4));
  f_bitvector_5 : register_bitvector_5 -> ((mword 5));
  f_bitvector_64 : register_bitvector_64 -> ((mword 64));
  f_bitvector_704 : register_bitvector_704 -> ((mword 704));
  f_bitvector_exp_8 : register_bitvector_exp_8 -> ((mword (2 ^ 8)));
  f_bool : register_bool -> bool;
  f_list_PMA_Region : register_list_PMA_Region -> ((list PMA_Region));
  f_option_bitvector_64 : register_option_bitvector_64 -> ((option (mword ((if 64 =? 32 then 34 else 64)))));
  f_option_tuple__range_0_15_tdata : register_option_tuple__range_0_15_tdata -> ((option ((Z * tdata))));
  f_option_tuple__range_3_31_event_csr : register_option_tuple__range_3_31_event_csr -> ((option ((Z * event_csr))));
  f_vector_16_Trigger : register_vector_16_Trigger -> ((vec Trigger 16));
  f_vector_32_bitvector_64 : register_vector_32_bitvector_64 -> ((vec (mword 64) 32));
  f_vector_64_bitvector_64 : register_vector_64_bitvector_64 -> ((vec (mword 64) 64));
  f_vector_64_bitvector_8 : register_vector_64_bitvector_8 -> ((vec (mword 8) 64));
  f_vector_64_option_TLB_Entry : register_vector_64_option_TLB_Entry -> ((vec (option TLB_Entry) (2 ^ 6)));
}.

(** The value of register [r]. *)
Definition rd (rf : regfile) (r : register) : type_of_register r :=
  match r return type_of_register r with
  | R_HartState n => f_HartState rf n
  | R_Privilege n => f_Privilege rf n
  | R_bitvector_1 n => f_bitvector_1 rf n
  | R_bitvector_128 n => f_bitvector_128 rf n
  | R_bitvector_192 n => f_bitvector_192 rf n
  | R_bitvector_3 n => f_bitvector_3 rf n
  | R_bitvector_32 n => f_bitvector_32 rf n
  | R_bitvector_320 n => f_bitvector_320 rf n
  | R_bitvector_4 n => f_bitvector_4 rf n
  | R_bitvector_5 n => f_bitvector_5 rf n
  | R_bitvector_64 n => f_bitvector_64 rf n
  | R_bitvector_704 n => f_bitvector_704 rf n
  | R_bitvector_exp_8 n => f_bitvector_exp_8 rf n
  | R_bool n => f_bool rf n
  | R_list_PMA_Region n => f_list_PMA_Region rf n
  | R_option_bitvector_64 n => f_option_bitvector_64 rf n
  | R_option_tuple__range_0_15_tdata n => f_option_tuple__range_0_15_tdata rf n
  | R_option_tuple__range_3_31_event_csr n => f_option_tuple__range_3_31_event_csr rf n
  | R_vector_16_Trigger n => f_vector_16_Trigger rf n
  | R_vector_32_bitvector_64 n => f_vector_32_bitvector_64 rf n
  | R_vector_64_bitvector_64 n => f_vector_64_bitvector_64 rf n
  | R_vector_64_bitvector_8 n => f_vector_64_bitvector_8 rf n
  | R_vector_64_option_TLB_Entry n => f_vector_64_option_TLB_Entry rf n
  end.

